{
  "results": [
    {
      "id": "h01",
      "action": "keep",
      "text": "승인 A, B, C를 모두 받은 경우에만 배포하세요.",
      "reason": "세 승인을 모두 받아야 한다는 필수 조건이 명확합니다."
    },
    {
      "id": "h02",
      "action": "keep",
      "text": "관리자 계정을 제외한 모든 정식 계정은 90일마다 비밀번호를 바꿔야 합니다.",
      "reason": "적용 대상, 관리자 계정의 제외, 변경 주기가 명확합니다."
    },
    {
      "id": "h03",
      "action": "keep",
      "text": "손잡이를 당긴 채로 문을 밀어 여세요.",
      "reason": "손잡이를 당긴 상태를 유지하면서 문을 여는 행동이 명확합니다."
    },
    {
      "id": "h04",
      "action": "keep",
      "text": "앱을 종료한 뒤 업데이트를 설치하고 앱을 다시 켜세요.",
      "reason": "종료, 설치, 재시작의 필수 순서가 명확합니다."
    },
    {
      "id": "h05",
      "action": "keep",
      "text": "모든 로그가 정상인 것은 아닙니다.",
      "reason": "전체가 정상이라는 판단을 부정하며, 개별 로그의 상태는 특정하지 않습니다."
    },
    {
      "id": "h06",
      "action": "clarify",
      "text": "새 드라이버를 설치하지 않은 장비를 점검에서 제외하라는 뜻인가요, 아니면 그 장비만 점검하는 것을 금지한다는 뜻인가요?",
      "reason": "‘만’과 부정이 결합해 금지하는 행동을 두 가지로 해석할 수 있습니다."
    },
    {
      "id": "h07",
      "action": "clarify",
      "text": "금액을 수정한 사람은 정 연구원인가요, 한 연구원인가요?",
      "reason": "‘그’가 가리킬 수 있는 사람이 둘이며 수정자는 확인되지 않았습니다."
    },
    {
      "id": "h08",
      "action": "rewrite",
      "text": "한 연구원이 금액을 수정했습니다.",
      "reason": "문맥에서 확인된 수정자를 밝혀 대명사의 모호함을 없앴습니다."
    },
    {
      "id": "h09",
      "action": "keep",
      "text": "호환성 검토를 진행했습니다.",
      "reason": "검토를 했다는 이력을 나타내며 완료 여부를 확정하지 않습니다."
    },
    {
      "id": "h10",
      "action": "keep",
      "text": "내일 백업을 복원할 예정입니다.",
      "reason": "내일의 계획을 나타내며 복원을 이미 실행했다는 뜻이 아닙니다."
    },
    {
      "id": "h11",
      "action": "keep",
      "text": "검사가 끝난 임시 사본은 지워도 됩니다.",
      "reason": "검사 완료를 조건으로 삭제를 허용하며 의무로 표현하지 않습니다."
    },
    {
      "id": "h12",
      "action": "keep",
      "text": "이 센서는 USB로 데이터를 전송할 수 있습니다.",
      "reason": "지원하는 전송 능력을 나타내며 현재 연결 상태를 주장하지 않습니다."
    },
    {
      "id": "h13",
      "action": "keep",
      "text": "이 버전에서는 일부 플러그인이 작동하지 않을 수 있습니다.",
      "reason": "일부 플러그인의 작동 실패 가능성을 명확히 나타냅니다."
    },
    {
      "id": "h14",
      "action": "keep",
      "text": "연결이 끊기면 인증을 다시 받아야 합니다.",
      "reason": "연결 끊김을 조건으로 재인증 의무를 명확히 나타냅니다."
    },
    {
      "id": "h15",
      "action": "keep",
      "text": "팀은 새 분석 도구의 도입을 승인했습니다.",
      "reason": "조직 배치를 뜻하는 도입과 그 승인 사실을 정확히 표현합니다."
    },
    {
      "id": "h16",
      "action": "keep",
      "text": "원본 로그는 보존 기간이 끝날 때까지 보존해야 합니다.",
      "reason": "원본을 보존할 의무와 그 기간이 명확합니다."
    },
    {
      "id": "h17",
      "action": "keep",
      "text": "변경 사항을 보내려면 동기화 버튼을 누르세요.",
      "reason": "실제 버튼 이름과 실행 목적이 명확합니다."
    },
    {
      "id": "h18",
      "action": "keep",
      "text": "알림 설정이 저장되었습니다.",
      "reason": "행위자보다 중요한 설정 저장 결과를 자연스럽게 알립니다."
    },
    {
      "id": "h19",
      "action": "keep",
      "text": "승인 대기",
      "reason": "승인 상태를 표시하는 표 셀에 적합한 짧은 표현입니다."
    },
    {
      "id": "h20",
      "action": "keep",
      "text": "오늘 보내드린 수정안을 검토해 주시겠습니까?",
      "reason": "검토 대상과 정중한 요청의 기능이 명확합니다."
    },
    {
      "id": "h21",
      "action": "keep",
      "text": "10분 동안 측정한 평균 응답 시간이 800ms에서 600ms로 줄었습니다.",
      "reason": "측정 기간, 평균값, 비교값과 단위가 명확합니다."
    },
    {
      "id": "h22",
      "action": "keep",
      "text": "배포 이후 오류율이 높아졌습니다.",
      "reason": "시간적 선후와 관측된 증가를 나타내며 인과관계를 확정하지 않습니다."
    },
    {
      "id": "h23",
      "action": "rewrite",
      "text": "담당자는 원본을 변경하지 않는 범위에서 적절한 복구 방법을 선택하세요.",
      "reason": "선택할 주체를 자연스럽게 표시하고 원본 변경 금지와 방법 선택의 위임을 유지했습니다."
    },
    {
      "id": "h24",
      "action": "rewrite",
      "text": "장애가 나면 장애대응 절차 B-7에 따라 대응하세요.",
      "reason": "문맥에서 확인된 참조 절차를 구체적으로 밝혔습니다."
    },
    {
      "id": "s01",
      "action": "keep",
      "text": "문제가 있을 수 있습니다.",
      "reason": "경고 대상이 공유되어 있으며 문제의 가능성을 자연스럽게 전달합니다."
    },
    {
      "id": "s02",
      "action": "clarify",
      "text": "오류를 처리할 때 어떤 결과를 목표로 해야 하나요?",
      "reason": "처리 목적이나 기준이 없어 필요한 행동을 정할 수 없습니다."
    }
  ]
}
